<?php
/** Inventory-only import ledger; snapshots and product writes share the SQL transaction. */
class InventoryVersions {
    private const FIELDS=['sku','name','description','image','social_image','gallery','link','price','status','color','stock_online','stock_total','sizes','size_chart','size_chart_template_id','priority','variants','uploaded_to_site','uploaded_by','is_manual_image','approvals_stage1','approvals_stage2','rejection_reason','rejection_by','rejection_side','rejections_history','content_gen_requested','publish_priority','reference_gallery','images_list','warehouses_stock','warehouse_details','model_code','stage1_decision','stage2_decision','size_chart_uploaded','size_chart_uploaded_at','website_sync'];
    public static function init(){if(!getConn()->query('CREATE TABLE IF NOT EXISTS inventory_version_chunks (snapshot VARCHAR(64) NOT NULL, chunk_no INTEGER NOT NULL, data LONGTEXT NOT NULL, PRIMARY KEY(snapshot,chunk_no))'))throw new RuntimeException('ایجاد فضای نسخه ناموفق بود.');if(!getConn()->query('CREATE TABLE IF NOT EXISTS inventory_import_versions (id VARCHAR(64) PRIMARY KEY, project_id VARCHAR(128) NOT NULL, source VARCHAR(16) NOT NULL, state VARCHAR(20) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, actor VARCHAR(128) NOT NULL, data LONGTEXT NOT NULL)'))throw new RuntimeException('ایجاد سابقهٔ واردسازی ناموفق بود.');}
    public static function lockProject($pid){$conn=getConn();foreach(['SELECT id FROM projects WHERE id = ?','SELECT id FROM products WHERE project_id = ?'] as $sql){if(!($conn instanceof SQLite3ToMysqliWrapper))$sql.=' FOR UPDATE';$q=$conn->prepare($sql);$q->bind_param('s',$pid);if(!$q->execute())throw new RuntimeException('قفل محصولات آماده نیست.');$q->get_result();$q->close();}}
    private static function canonical($v){if(is_array($v)){foreach($v as &$x)$x=self::canonical($x);unset($x);if($v&&array_keys($v)!==range(0,count($v)-1))ksort($v);}return $v;}
    private static function hash($v){return hash('sha256',json_encode(self::canonical($v),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));}
    private static function values($p){$out=[];foreach(self::FIELDS as $f)if(array_key_exists($f,$p)){$v=$p[$f];if(in_array($f,['stock_total','stock_online','price'],true)&&is_numeric($v))$v=(float)$v;$out[$f]=$v;}return $out;}
    private static function map($products){$out=[];foreach($products as $p)$out[(string)$p['id']]=$p;return $out;}
    /** Keep large ERP snapshots below MySQL max_allowed_packet, including bound parameters. */
    private static function pack($payload) {
        $json=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
        if(strlen($json)<131072)return $json;
        $snapshot=bin2hex(random_bytes(32));$chunks=str_split(base64_encode($json),131072);
        try {foreach($chunks as $i=>$chunk){$q=getConn()->prepare('INSERT INTO inventory_version_chunks(snapshot,chunk_no,data) VALUES (?,?,?)');$q->bind_param('sis',$snapshot,$i,$chunk);if(!$q->execute())throw new RuntimeException('ثبت بخش نسخه ناموفق بود.');$q->close();}}
        catch(Throwable $e){self::removeChunks($snapshot);throw $e;}
        return json_encode(['_snapshot'=>$snapshot,'chunks'=>count($chunks),'sha256'=>hash('sha256',$json)],JSON_THROW_ON_ERROR);
    }
    private static function removeChunks($snapshot){$q=getConn()->prepare('DELETE FROM inventory_version_chunks WHERE snapshot = ?');$q->bind_param('s',$snapshot);$q->execute();$q->close();}
    private static function unpack($data){
        $value=json_decode($data,true,512,JSON_THROW_ON_ERROR);if(!isset($value['_snapshot']))return $value;
        $q=getConn()->prepare('SELECT chunk_no,data FROM inventory_version_chunks WHERE snapshot = ? ORDER BY chunk_no');$q->bind_param('s',$value['_snapshot']);$q->execute();$r=$q->get_result();$encoded='';$n=0;while($row=$r->fetch_assoc()){if((int)$row['chunk_no']!==$n++)throw new RuntimeException('نسخه ناقص است.');$encoded.=$row['data'];}$q->close();$json=base64_decode($encoded,true);
        if($n!==$value['chunks']||$json===false||!hash_equals($value['sha256'],hash('sha256',$json)))throw new RuntimeException('نسخه ناقص است.');return json_decode($json,true,512,JSON_THROW_ON_ERROR);
    }
    public static function read($pid,$id){if(!is_string($id)||!preg_match('/^[a-f0-9]{48,64}$/D',$id))throw new RuntimeException('شناسهٔ نسخه معتبر نیست.');$q=getConn()->prepare('SELECT * FROM inventory_import_versions WHERE id = ? AND project_id = ?');$q->bind_param('ss',$id,$pid);$q->execute();$row=$q->get_result()->fetch_assoc();$q->close();if(!$row)throw new RuntimeException('نسخه در این پروژه یافت نشد.');$row['payload']=self::unpack($row['data']);unset($row['data']);return $row;}
    private static function write($run){
        $q=getConn()->prepare('SELECT data FROM inventory_import_versions WHERE id = ? AND project_id = ?');$q->bind_param('ss',$run['id'],$run['project_id']);$q->execute();$old=$q->get_result()->fetch_assoc();$q->close();$marker=json_decode($old['data']??'{}',true);
        $data=self::pack($run['payload']);$at=time();$q=getConn()->prepare('UPDATE inventory_import_versions SET state = ?, updated_at = ?, data = ? WHERE id = ? AND project_id = ?');$q->bind_param('sisss',$run['state'],$at,$data,$run['id'],$run['project_id']);if(!$q->execute())throw new RuntimeException('ثبت نسخهٔ موجودی ناموفق بود.');$q->close();
        if(isset($marker['_snapshot']))self::removeChunks($marker['_snapshot']);
    }
    public static function prepare($project,$source,$id,$planned,$actor=null){
        $pid=$project['id'];$current=self::map($project['products']??[]);
        $check=getConn()->prepare('SELECT id FROM inventory_import_versions WHERE id = ?');$check->bind_param('s',$id);$check->execute();$exists=$check->get_result()->fetch_assoc();$check->close();
        if($exists){$old=self::read($pid,$id);if($old['state']!=='prepared')throw new RuntimeException('این واردسازی قبلاً ثبت شده است.');foreach($old['payload']['targets'] as $key=>$_)if(self::hash($old['payload']['before'][$key]??null)!==self::hash($current[$key]??null))throw new RuntimeException('محصولی تغییر کرده؛ پیش‌نمایش جدید بگیرید.');return $old;}
        $before=[];$after=[];foreach($planned as $p){$key=(string)$p['id'];$old=$current[$key]??null;if($old&&self::hash(self::values($old))===self::hash(self::values($p)))continue;if($old)$before[$key]=$old;$after[$key]=$p;}
        $payload=['before'=>$before,'after'=>[],'planned'=>$after,'targets'=>array_fill_keys(array_keys($after),true)];$data=self::pack($payload);$state='prepared';$at=time();$actor=(string)($actor??($_SESSION['user']['username']??'scheduler'));$q=getConn()->prepare('INSERT INTO inventory_import_versions (id,project_id,source,state,created_at,updated_at,actor,data) VALUES (?,?,?,?,?,?,?,?)');$q->bind_param('ssssiiss',$id,$pid,$source,$state,$at,$at,$actor,$data);if(!$q->execute()){error_log('Inventory snapshot INSERT failed; SQL errno='.(getConn()->errno??0).'; bytes='.strlen($data));$marker=json_decode($data,true);if(isset($marker['_snapshot']))self::removeChunks($marker['_snapshot']);throw new RuntimeException('ثبت نقطهٔ بازگشت ناموفق بود؛ تغییری اعمال نشد.');}$q->close();return self::read($pid,$id);
    }
    public static function record($pid,$id,$persisted,$done=true){
        $run=self::read($pid,$id);if(in_array($run['state'],['rolled_back','cancelled','stopped'],true))throw new RuntimeException('این واردسازی لغو یا بازگردانی شده است.');
        foreach($persisted as $p){$key=(string)$p['id'];if(empty($run['payload']['targets'][$key]))continue;$old=$run['payload']['before'][$key]??null;
            if(!$old){$brief=array_intersect_key($p,array_flip(['id','name','color','sku','stock_total','variants']));$brief['_new_record_hash']=self::hash($p);$run['payload']['after'][$key]=$brief;}
            else{$a=self::values($old);$b=self::values($p);$pre=['id'=>$key,'name'=>$old['name']??'','color'=>$old['color']??'','sku'=>$old['sku']??'','stock_total'=>$old['stock_total']??null];$post=['id'=>$key,'name'=>$p['name']??'','color'=>$p['color']??'','sku'=>$p['sku']??'','stock_total'=>$p['stock_total']??null];$fields=[];foreach(array_unique(array_merge(array_keys($a),array_keys($b))) as $f)if(self::hash($a[$f]??null)!==self::hash($b[$f]??null)){$fields[]=$f;if(array_key_exists($f,$old))$pre[$f]=$old[$f];if(array_key_exists($f,$p))$post[$f]=$p[$f];}
                if($fields){$run['payload']['before'][$key]=$pre;$run['payload']['after'][$key]=$post;}else{unset($run['payload']['before'][$key],$run['payload']['after'][$key]);}}
            unset($run['payload']['planned'][$key]);
        }
        $run['state']=$done?'applied':'applying';if($done)unset($run['payload']['planned']);self::write($run);return $run;
    }
    public static function cancel($pid,$id){$run=self::read($pid,$id);if(!in_array($run['state'],['prepared','applying'],true))throw new RuntimeException('این واردسازی قابل لغو نیست.');$run['state']=$run['payload']['after']?'stopped':'cancelled';unset($run['payload']['planned']);self::write($run);}
    public static function changes($pid,$id,$page=1,$size=25){$run=self::read($pid,$id);$rows=[];$before=$run['payload']['before'];$after=$run['state']==='prepared'?($run['payload']['planned']??[]):$run['payload']['after'];$counts=['new'=>0,'updated'=>0,'zeroed'=>0];foreach($after as $key=>$p){$old=$before[$key]??null;$a=self::values($old??[]);$b=self::values($p);$fields=[];foreach(array_unique(array_merge(array_keys($a),array_keys($b))) as $f)if(self::hash($a[$f]??null)!==self::hash($b[$f]??null))$fields[]=$f;if($old&&!$fields)continue;$kind=$old?'updated':'new';$counts[$kind]++;if($old&&is_numeric($old['stock_total']??null)&&(float)$old['stock_total']>0&&(float)($p['stock_total']??0)===0.0)$counts['zeroed']++;$rows[]=['id'=>$key,'name'=>$p['name']??$key,'color'=>$p['color']??'','sku'=>$p['sku']??'','type'=>$kind,'before_stock'=>$old['stock_total']??null,'after_stock'=>$p['stock_total']??null,'fields'=>$fields,'field_values'=>array_map(static fn($f)=>['field'=>$f,'before'=>$a[$f]??null,'after'=>$b[$f]??null],$fields),'before_variants'=>$old['variants']??[],'after_variants'=>$p['variants']??[]];}$page=max(1,(int)$page);$size=min(50,max(1,(int)$size));return ['id'=>$id,'source'=>$run['source'],'state'=>$run['state'],'created_at'=>(int)$run['created_at'],'actor'=>$run['actor'],'counts'=>$counts,'total'=>count($rows),'page'=>$page,'pages'=>max(1,(int)ceil(count($rows)/$size)),'rows'=>array_slice($rows,($page-1)*$size,$size)];}
    public static function history($pid){$q=getConn()->prepare('SELECT id, source, state, created_at, updated_at, actor FROM inventory_import_versions WHERE project_id = ? ORDER BY created_at DESC, id DESC LIMIT 30');$q->bind_param('s',$pid);$q->execute();$result=$q->get_result();$rows=[];while($r=$result->fetch_assoc())$rows[]=$r;$q->close();return $rows;}
    public static function rollback($pid,$id){$conn=getConn();if(!$conn->begin_transaction())throw new RuntimeException('شروع بازگردانی ناموفق بود.');try{self::lockProject($pid);$run=self::read($pid,$id);if($run['state']==='rolled_back'){$conn->rollback();return ['status'=>'rolled_back','id'=>$id,'already_done'=>true];}if(!in_array($run['state'],['applied','applying','stopped'],true))throw new RuntimeException('نسخه هنوز اعمال نشده یا قابل بازگشت نیست.');$project=getCurrentProject($pid,true);$current=self::map($project['products']??[]);$restore=[];$remove=[];$conflicts=[];
        foreach($run['payload']['after'] as $key=>$after){$before=$run['payload']['before'][$key]??null;$now=$current[$key]??null;if($before&&self::hash(self::values($before))===self::hash(self::values($after)))continue;if(!$before){if(!$now||self::hash($now)!==($after['_new_record_hash']??self::hash($after))){$conflicts[]=$after['name']??$key;continue;}$remove[]=$key;continue;}if(!$now){$conflicts[]=$before['name']??$key;continue;}$a=self::values($before);$b=self::values($after);$c=self::values($now);$changed=false;foreach(array_unique(array_merge(array_keys($a),array_keys($b))) as $f){if(self::hash($a[$f]??null)===self::hash($b[$f]??null))continue;if(self::hash($c[$f]??null)!==self::hash($b[$f]??null)){$conflicts[]=$before['name']??$key;continue;}if(array_key_exists($f,$before))$now[$f]=$before[$f];else unset($now[$f]);$changed=true;}if($changed)$restore[]=$now;}
        if($conflicts)throw new RuntimeException('برای حفظ ویرایش‌های بعدی، بازگردانی متوقف شد. تعارض در: '.implode('، ',array_slice(array_unique($conflicts),0,8)));
        if(!empty($project['settings']['tiam_inventory'])&&!canAccessFeature('settings','use'))throw new RuntimeException('بازگردانی این پروژه به دسترسی تنظیمات برای توقف امن همگام‌سازی تیام نیاز دارد.');
        if($restore&&!db_save_project($project,$restore,null,false))throw new RuntimeException('بازگردانی محصولات ناموفق بود.');foreach($remove as $key){$q=$conn->prepare('DELETE FROM products WHERE id = ? AND project_id = ?');$q->bind_param('ss',$key,$pid);if(!$q->execute())throw new RuntimeException('حذف رکورد ایجادشده توسط واردسازی ناموفق بود.');$q->close();}
        if(!empty($project['settings']['tiam_inventory'])){$project['settings']['tiam_inventory']['enabled']=false;unset($project['settings']['tiam_inventory']['approved']);}$settings=json_encode($project['settings'],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$q=$conn->prepare('UPDATE projects SET settings = ? WHERE id = ?');$q->bind_param('ss',$settings,$pid);if(!$q->execute())throw new RuntimeException('توقف زمان‌بندی ناموفق بود.');$q->close();
        $run['state']='rolled_back';$run['payload']['rollback_actor']=$_SESSION['user']['username']??'';self::write($run);if(!$conn->commit())throw new RuntimeException('ثبت بازگردانی ناموفق بود.');if(class_exists('MaarkshoCache'))MaarkshoCache::delete('project_full_'.$pid);return ['status'=>'rolled_back','id'=>$id,'restored'=>count($restore),'removed'=>count($remove),'daily_sync_paused'=>true];
    }catch(Throwable $e){$conn->rollback();throw $e;}}
}
